import { afterAll, bench, describe } from 'vitest';
import {
  __date,
  __number,
  __plural,
  createI18n,
  type Catalog,
  type MessageContext,
} from '../packages/precompile-intl-runtime/src/index.js';
// The exact pre-refactor build is generated by `npm run bench:prepare`.
// @ts-expect-error The historical JavaScript build intentionally has no local declaration file.
import * as legacy from '../.benchmark-cache/baseline/packages/precompile-intl-runtime/dist/modules/index.js';

const iterations = 1_000;
const date = new Date('2024-06-12T13:45:00.000Z');
const pluralOptions = { o: 'one item', h: 'many items' } as const;

const currentMessages = {
  en: {
    plain: 'Plain message',
    'nested.title': 'Nested title',
    greeting: (_context: MessageContext, values) => `Hello ${values.name}`,
    items: (context: MessageContext, values) =>
      __plural(context, Number(values.count), pluralOptions),
    amount: (context: MessageContext, values) => __number(context, Number(values.amount)),
    published: (context: MessageContext, values) => __date(context, Number(values.date), 'medium'),
  },
} satisfies Record<string, Catalog>;

const current = createI18n({
  locale: 'en-US',
  fallbackLocale: 'en',
  messages: currentMessages,
  warnOnMissingMessages: false,
});

legacy.init({
  initialLocale: 'en-US',
  fallbackLocale: 'en',
  warnOnMissingMessages: false,
});
legacy.addMessages('en', {
  plain: 'Plain message',
  'nested.title': 'Nested title',
  greeting: (name: unknown) => `Hello ${name}`,
  items: (count: number) => legacy.__plural(count, pluralOptions),
  amount: (amount: number) => legacy.__number(amount),
  published: (value: number) => legacy.__date(value, 'medium'),
});

let legacyTranslate!: (id: string, options?: { values?: Record<string, unknown> }) => string;
const unsubscribe = legacy.t.subscribe((translate: typeof legacyTranslate) => {
  legacyTranslate = translate;
});

function repeat(callback: (index: number) => string): string {
  let result = '';
  for (let index = 0; index < iterations; index += 1) result = callback(index);
  return result;
}

function repeat100(callback: (index: number) => string): string {
  let result = '';
  for (let index = 0; index < 100; index += 1) result = callback(index);
  return result;
}

describe('1,000 translations per sample', () => {
  bench('legacy: cached plain lookup', () => repeat(() => legacyTranslate('plain')));
  bench('current: cached plain lookup', () => repeat(() => current('plain')));

  bench('legacy: interpolation', () =>
    repeat((index) => legacyTranslate('greeting', { values: { name: index } })),
  );
  bench('current: interpolation', () => repeat((index) => current('greeting', { name: index })));

  bench('legacy: cardinal plural', () =>
    repeat((index) => legacyTranslate('items', { values: { count: index % 5 } })),
  );
  bench('current: cardinal plural', () =>
    repeat((index) => current('items', { count: index % 5 })),
  );

  bench('legacy: representative mix', () =>
    repeat((index) => {
      switch (index % 5) {
        case 0:
          return legacyTranslate('plain');
        case 1:
          return legacyTranslate('greeting', { values: { name: index } });
        case 2:
          return legacyTranslate('items', { values: { count: index % 5 } });
        case 3:
          return legacyTranslate('amount', { values: { amount: 12_345.67 + index } });
        default:
          return legacyTranslate('published', { values: { value: date.valueOf() + index } });
      }
    }),
  );
  bench('current: representative mix', () =>
    repeat((index) => {
      switch (index % 5) {
        case 0:
          return current('plain');
        case 1:
          return current('greeting', { name: index });
        case 2:
          return current('items', { count: index % 5 });
        case 3:
          return current('amount', { amount: 12_345.67 + index });
        default:
          return current('published', { date: date.valueOf() + index });
      }
    }),
  );
});

describe('100 Intl formats per sample', () => {
  bench('legacy: number', () =>
    repeat100((index) => legacyTranslate('amount', { values: { amount: 12_345.67 + index } })),
  );
  bench('current: number', () =>
    repeat100((index) => current('amount', { amount: 12_345.67 + index })),
  );
  bench('legacy: date', () =>
    repeat100((index) =>
      legacyTranslate('published', { values: { value: date.valueOf() + index } }),
    ),
  );
  bench('current: date', () =>
    repeat100((index) => current('published', { date: date.valueOf() + index })),
  );
});

afterAll(() => unsubscribe());
